'use client';
import {useEffect,useRef,useState} from 'react';
import {GroupBillingAccount} from './group-billing-account';
import {hotelRpc,usd,type Booking,type Room,type RoomType} from '@/lib/pilot';
type Summary={id:string;name:string;created_at:string};
type Cursor={time:string;id:string}|null;
type Props={billingActor?:string;tenant:string;property:string;rooms?:Room[];types?:RoomType[];onStay:(stay:Booking)=>void};
export function ReservationGroups(props:Props){return <Groups key={props.tenant+':'+props.property} {...props}/>}
function Groups({billingActor,tenant,property,rooms=[],types=[],onStay}:Props){
 const [rows,setRows]=useState<Summary[]>([]),[next,setNext]=useState<Cursor>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[group,setGroup]=useState<{id:string;name:string;reservations:Booking[]}|null>(null);
 const alive=useRef(true),lock=useRef(false);
 async function page(cursor:Cursor){if(lock.current)return;lock.current=true;setBusy(true);setError('');try{const r=await hotelRpc<{items:Summary[];next:Cursor}>('groups',{p_tenant:tenant,p_property:property,p_before_time:cursor?.time??null,p_before_id:cursor?.id??null});if(alive.current){setRows(old=>cursor?[...old,...r.items.filter(x=>!old.some(y=>y.id===x.id))]:r.items);setNext(r.next)}}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to load groups.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 useEffect(()=>{alive.current=true;void page(null);return()=>{alive.current=false}},[]);
 async function open(id:string){if(lock.current)return;lock.current=true;setBusy(true);setError('');setGroup(null);try{const r=await hotelRpc<{id:string;name:string;reservations:Booking[]}>('group',{p_tenant:tenant,p_property:property,p_group:id});if(alive.current)setGroup(r)}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to open group.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section className="card"><div className="section-top"><h2>Reservation groups</h2><button className="secondary" disabled={busy} onClick={()=>{setGroup(null);void page(null)}}>Refresh groups</button></div>{error&&<p className="pilot-error" role="alert">{error}</p>}{busy&&<p role="status">Loading groups…</p>}<div className="pilot-settings">{rows.map(r=><p key={r.id}><button className="text-button" disabled={busy} onClick={()=>void open(r.id)}>{r.name}</button></p>)}{!busy&&!error&&!rows.length&&<p>No groups saved for this property.</p>}{next&&<button className="secondary" disabled={busy} onClick={()=>void page(next)}>Load older groups</button>}{group&&<section><h3>{group.name}</h3>{billingActor&&<GroupBillingAccount actor={billingActor} tenant={tenant} property={property} group={group}/>}<p>{group.reservations.length} reservations · {group.reservations.filter(r=>r.status==='Confirmed').length} confirmed · {group.reservations.filter(r=>r.status==='In house').length} in house · {group.reservations.filter(r=>r.status==='Cancelled').length} cancelled</p><p>Stay values are reservation prices, not payment balances. Cancelled stays retain their recorded values.</p>{group.reservations.map(r=><section className="pilot-settings" key={r.id}><button className="text-button" disabled={busy} onClick={()=>onStay(r)}>{r.guest_name||'Guest'} · {r.arrival} to {r.departure} · {r.status}</button><dl><dt>Room type</dt><dd>{types.find(t=>t.id===r.room_type_id)?.name??'Not available'}</dd><dt>Assigned room</dt><dd>{r.physical_room_id?(rooms.find(room=>room.id===r.physical_room_id)?.label??'Room details unavailable'):'Unassigned'}</dd><dt>Guests</dt><dd>{r.guests??'Not available'}</dd><dt>Stay value</dt><dd>{r.guest_total_minor===null||r.guest_total_minor===undefined?'Not available':usd(r.guest_total_minor)}</dd></dl></section>)}</section>}</div></section>
}
